input.new_string:
void skip(int i) {
	while (i-- > 0) {
		linecount++;
		if (linecount >= (tui_active ? tui_pageheight() : 23))
			pause(0);
		else if (tui_active)
			tui_puts("\n");
		else
			putchar('\n');
	}
}


void proutn(char *s) {
	if (tui_active)
		tui_puts(s);
	else
		fputs(s, stdout);
}

void prout(char *s) {
	proutn(s);
	skip(1);
}

void proutf(const char *fmt, ...) {
	char buf[512];
	va_list ap;
	va_start(ap, fmt);
	vsnprintf(buf, sizeof(buf), fmt, ap);
	va_end(ap);
	proutn(buf);
}

void prouts(char *s) {
	clock_t endTime;
	if (tui_active) {
		tui_puts_slow(s);
		return;
	}
	/* print slowly! */
	while (*s) {
		endTime = clock() + CLOCKS_PER_SEC*0.05;
		while (clock() < endTime) ;
		putchar(*s++);
		fflush(stdout);
	}
}

