/* What a grid cell and a status line are, for colouring.
 *
 * A cell is classified from the character the panel is about to show,
 * never from the game state behind it. When the sensors are damaged
 * every hidden cell reads as '-', so they all classify alike and
 * colour cannot become a way to see what a scan is hiding. */
enum cellclass {
	CELL_PLAIN,	/* empty space, grid labels */
	CELL_HOSTILE,	/* Klingons, Commanders, Romulans, Tholians */
	CELL_SHIP,	/* ours */
	CELL_BASE,
	CELL_STAR,
	CELL_PLANET,
	CELL_WEB,
	CELL_HIDDEN	/* masked by damaged sensors */
};

enum statusclass {
	STAT_PLAIN,
	STAT_GOOD,
	STAT_WARN,
	STAT_BAD,
	STAT_DOCKED
};

/* Panel formatters (tuifmt.c). Both read the global game state. */

/* Classify a cell the panel is about to draw, by the character itself.
 *
 * Taking the character rather than the quadrant contents is what keeps
 * colour honest: a cell the sensors are hiding has already become '-'
 * by the time it gets here, so there is nothing left to leak. */
int cell_class(char c) {
	switch (c) {
		case IHK: case IHC: case IHS: case IHR: case IHT:
			return CELL_HOSTILE;
		case IHE: case IHF:	return CELL_SHIP;
		case IHB:		return CELL_BASE;
		case IHSTAR:		return CELL_STAR;
		case IHP:		return CELL_PLANET;
		case IHWEB:		return CELL_WEB;
		case '-':		return CELL_HIDDEN;
		default:		return CELL_PLAIN;
	}
}

/* Whether a status line is worth reading twice: the fields that tell a
 * player something is wrong, and the two that say it is not. */
int status_class(int i) {
	switch (i) {
		case 2:		/* condition */
			if (condit == IHDOCKED) return STAT_DOCKED;
			switch (condition_now()) {
				case IHRED:	return STAT_BAD;
				case IHYELLOW:	return STAT_WARN;
				default:	return STAT_GOOD;
			}
		case 4:		/* life support */
			if (damage[DLIFSUP] == 0.0) return STAT_GOOD;
			return condit == IHDOCKED ? STAT_WARN : STAT_BAD;
		case 8:		/* shields */
			if (damage[DSHIELD] != 0) return STAT_BAD;
			return shldup ? STAT_GOOD : STAT_WARN;
		default:
			return STAT_PLAIN;
	}
}

void fmt_quad_line(int i, char *buf) {

static WINDOW *wquad, *wstat, *wmsg;
static int use_colour;

/* One pair per foreground; the background stays whatever the terminal
 * already uses, so the panels sit in the player's own colour scheme. */
#define CP_HOSTILE 1
#define CP_SHIP    2
#define CP_BASE    3
#define CP_STAR    4
#define CP_PLANET  5
#define CP_WEB     6
#define CP_GOOD    7
#define CP_WARN    8

static void start_colour(void) {
	short bg = -1;

	use_colour = has_colors();
	if (!use_colour) return;	/* the layout works without it */
	start_color();
	if (use_default_colors() == ERR)
		bg = COLOR_BLACK;
	init_pair(CP_HOSTILE, COLOR_RED, bg);
	init_pair(CP_SHIP, COLOR_WHITE, bg);
	init_pair(CP_BASE, COLOR_CYAN, bg);
	init_pair(CP_STAR, COLOR_YELLOW, bg);
	init_pair(CP_PLANET, COLOR_GREEN, bg);
	init_pair(CP_WEB, COLOR_MAGENTA, bg);
	init_pair(CP_GOOD, COLOR_GREEN, bg);
	init_pair(CP_WARN, COLOR_YELLOW, bg);
}

static chtype attr_for_cell(char c) {
	if (!use_colour) return A_NORMAL;
	switch (cell_class(c)) {
		case CELL_HOSTILE:	return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
		case CELL_SHIP:		return COLOR_PAIR(CP_SHIP) | A_BOLD;
		case CELL_BASE:		return COLOR_PAIR(CP_BASE) | A_BOLD;
		case CELL_STAR:		return COLOR_PAIR(CP_STAR);
		case CELL_PLANET:	return COLOR_PAIR(CP_PLANET);
		case CELL_WEB:		return COLOR_PAIR(CP_WEB);
		case CELL_HIDDEN:	return A_DIM;
		default:		return A_NORMAL;
	}
}

static chtype attr_for_status(int line) {
	if (!use_colour) return A_NORMAL;
	switch (status_class(line)) {
		case STAT_GOOD:		return COLOR_PAIR(CP_GOOD);
		case STAT_WARN:		return COLOR_PAIR(CP_WARN);
		case STAT_BAD:		return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
		case STAT_DOCKED:	return COLOR_PAIR(CP_BASE) | A_BOLD;
		default:		return A_NORMAL;
	}
}

/* Draw a grid line a cell at a time so each symbol carries its own
 * colour. Row labels and spacing classify as plain and stay uncoloured. */
static void draw_quad_line(int row, const char *s) {
	int i;

	wmove(wquad, row, 2);
	for (i = 0; s[i] != '\0'; i++) {
		chtype a = attr_for_cell(s[i]);
		if (a != A_NORMAL) wattron(wquad, a);
		waddch(wquad, (unsigned char)s[i]);
		if (a != A_NORMAL) wattroff(wquad, a);
	}
}

/* The label stays plain and the value takes the colour, so a glance
 * down the panel picks out the fields that are shouting. */
#define STATLABEL (14)		/* width fmt_status_line pads labels to */

static void draw_status_line(int row, int line, const char *s) {
	chtype a = attr_for_status(line);
	int i;

	wmove(wstat, row, 2);
	for (i = 0; s[i] != '\0'; i++) {
		if (i == STATLABEL && a != A_NORMAL) wattron(wstat, a);
		waddch(wstat, (unsigned char)s[i]);
	}
	if (a != A_NORMAL) wattroff(wstat, a);
}

